$(document).ready(function(){function stopAllVideosCard(){let $allVideos=$(".cos-slider-cards").find("video");$.each($allVideos,function(i,video){let $video=$(video);if(!video.paused){$video.trigger('pause')}})}
function startVideosCard(){stopAllVideosCard();const sliders=document.querySelectorAll(".cos-slider-cards");sliders.forEach((slider,i)=>{let $slider=$(slider);let videoFound=!1;let $slidesActive=$slider.find('.slick-active');$.each($slidesActive,function(key,slide){let $slide=$(slide);let $video=$slide.find('video');if($video.length>0){videoFound=!0;$video[0].playbackRate=1.5;$video.trigger('play');return!1}});if(!videoFound){let $video=$slider.find("video");if($video.length){let firstVideo=$video[0];firstVideo.play()}}})}
startVideosCard();let $cardVideos=$(".cos-slider-cards VIDEO");if($cardVideos.length>0){$(window).resize(function(){console.log('resizing window');startVideosCard()})}
$(".cos-slider-cards VIDEO").bind("ended",function(){stopAllVideosCard();playNextVideoCard($(this))});function playNextVideoCard($currentVideo){let currentVideoClass=$currentVideo.attr("class");let $allVideos=$currentVideo.closest(".cos-slider-cards").find(".slick-active video");if($allVideos.length==0){$allVideos=$currentVideo.closest(".cos-slider-cards").find("video")}
let found=!1;$.each($allVideos,function(i,video){let $video=$(video);if(currentVideoClass==$video.attr("class")){found=!0;let nextVideoIndex=i+1;if(nextVideoIndex<=$allVideos.length-1){let $nextVideo=$allVideos[nextVideoIndex];$nextVideo.playbackRate=1.5;$nextVideo.play()}else{let $nextVideo=$allVideos[0];$nextVideo.play()}}});if(!found){let $nextVideo=$allVideos[0];$nextVideo.play()}}
$(".cos-slider-cards").on("afterChange",function(){startVideosCard()});$("a.cosCard, #navbarSupportedContent .cosCard, .cosCardOld").not(".cosCard-nobg, .cos-card-post").hover(function(){if($(window).width()>767.98){$(this).find(".card-img-top").css({filter:"brightness(0.7)","-webkit-transition":"filter 1s","-moz-transition":"filter 1s","-ms-transition":"filter 1s","-o-transition":"filter 1s",transition:"filter 1s",})}},function(){if($(window).width()>767.98){$(this).find(".card-img-top").css({filter:"brightness(1)","-webkit-transition":"filter 1s","-moz-transition":"filter 1s","-ms-transition":"filter 1s","-o-transition":"filter 1s",transition:"filter 1s",})}})})